package br.com.sussmartcare.patientregistry.domain; import org.junit.jupiter.api.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; class PatientTest { @Test void provisionalCanBeResolvedWithoutChangingId(){var p=Patient.provisional("Paciente não identificado");var id=p.getId();p.confirmIdentity("Maria",null);assertEquals(id,p.getId());assertEquals(IdentityStatus.CONFIRMED,p.getIdentityStatus());} @Test void cannotMergeIntoItself(){var p=Patient.provisional("X");assertThrows(IllegalArgumentException.class,()->p.mergeInto(p.getId()));} }